from fractions import Fraction as F
import itertools
# motion work: (mp/i1)*(i2/hw)=1/12 with mp+i1=i2+hw=S
res=[]
for S in range(24,90):
    for mp in range(12,S-11):
        i1=S-mp
        for i2 in range(12,S-11):
            hw=S-i2
            if F(mp,i1)*F(i2,hw)==F(1,12): res.append((S,mp,i1,i2,hw))
print(res[:15])
# day: H(hw)->J(j1) ; j2->d ; (hw/j1)(j2/d)=1/2 given hw=?
for hw in sorted({r[4] for r in res})[:5]:
    out=[]
    for j1 in range(12,50):
      for j2 in range(12,50):
        for d in range(12,50):
          if F(hw,j1)*F(j2,d)==F(1,2) : out.append((j1,j2,d, max(j1,j2,d)))
    out.sort(key=lambda t:t[3]+t[0]+t[1]+t[2]); print(hw,out[:6])
# seconds chain
best=[]
rng=range(12,46)
import math
sols=[]
for mb in range(12,46):
  for x1a in range(12,46):
    r1=F(mb,x1a)
    if r1<1 or r1>5: continue
    for x1b in range(12,46):
      for x2a in range(12,46):
        r2=F(x1b,x2a)
        if r2<1 or r2>5: continue
        r12=r1*r2
        if 60/r12 > 25 or 60/r12<1: continue
        rem=60/r12
        for x2b in range(12,46):
          for x3a in range(12,46):
            r3=F(x2b,x3a)
            if r3<1 or r3>5: continue
            rr=rem/r3
            if rr<1 or rr>5: continue
            # x3b/sa = rr
            for sa in range(12,46):
              x3b=rr*sa
              if x3b.denominator==1 and 12<=x3b<=46:
                sols.append((mb,x1a,x1b,x2a,x2b,x3a,int(x3b),sa))
print(len(sols))
sols.sort(key=lambda s:max(s)*100+sum(s))
for s in sols[:10]: print(s,max(s),sum(s))
